/**
 * Interprets the TASKS_NON_ADMIN_COMPLETE_PERMISSION org preference, which
 * decides which non-admin users may close a task - set it to done or rejected,
 * since both take it out of the open queue. Organisation admins always may.
 *
 * The preference is a raw string with three recognised values: "default" keeps the
 * behaviour that predates the setting, "assigned" limits completion to tasks
 * assigned to the user or one of their groups, "none" leaves it to admins.
 *
 * An org that never configured the setting has no stored row, and that
 * unconfigured state resolves to "default" so nothing changes until an admin opts
 * in. A value that is present but unrecognised is a misconfiguration and fails
 * closed to "none", matching the backend.
 */

import { logger } from 'src/utils/logger';

export type TaskCompletePermission = 'none' | 'assigned' | 'default';

const RECOGNISED_MODES: readonly TaskCompletePermission[] = [
  'none',
  'assigned',
  'default',
];

const UNCONFIGURED_DEFAULT: TaskCompletePermission = 'default';
const INVALID_VALUE_FALLBACK: TaskCompletePermission = 'none';

// The gate runs for every task row on every re-render, so a fallback would be
// reported on each call. Report each distinct unrecognised value once instead.
const reportedValues = new Set<string>();

export function toTaskCompletePermission(
  value: unknown,
): TaskCompletePermission {
  const mode = String(value ?? '')
    .trim()
    .toLowerCase();
  if ((RECOGNISED_MODES as readonly string[]).includes(mode)) {
    return mode as TaskCompletePermission;
  }

  if (mode === '') {
    return UNCONFIGURED_DEFAULT;
  }

  const seenKey = `${typeof value}:${String(value)}`;
  if (!reportedValues.has(seenKey)) {
    reportedValues.add(seenKey);
    logger.warn(`[TaskCompletePermission] TASKS_NON_ADMIN_COMPLETE_PERMISSION is unrecognised (${typeof value} ${JSON.stringify(value)}), falling back to "${INVALID_VALUE_FALLBACK}" (admin-only)`);
  }
  return INVALID_VALUE_FALLBACK;
}

// Exported for tests: the report dedupe is module state that must not leak
// between cases.
export function resetTaskCompletePermissionReporting(): void {
  reportedValues.clear();
}

export interface TaskCompleteGateInput {
  isAdmin: boolean;
  /** Raw TASKS_NON_ADMIN_COMPLETE_PERMISSION value: one of the three modes. */
  permission: string | null | undefined;
  /** tasks.store.isHasAccess(row): the task is assigned to somebody else. */
  taskBelongsToSomeoneElse: boolean;
}

/**
 * The single "may close this task" (done or rejected) predicate shared by every
 * task surface, so a control is only offered when the backend will accept it.
 *
 * Only the setting is decided here. In "default" the surfaces keep whatever rules
 * they had before the setting existed. A task nobody is assigned to yields
 * taskBelongsToSomeoneElse=true for a non-admin and is refused server-side in
 * "assigned" as well.
 */
export function canMarkTaskDone({
  isAdmin,
  permission,
  taskBelongsToSomeoneElse,
}: TaskCompleteGateInput): boolean {
  if (isAdmin) {
    return true;
  }

  const mode = toTaskCompletePermission(permission);
  if (mode === 'default') {
    return true;
  }
  if (mode === 'none') {
    return false;
  }

  return !taskBelongsToSomeoneElse;
}
